/**
 * Builds one invoice per DST-aware daily billing window in the range.
 * Remaining credit balances carry across windows; input grants are not mutated.
 */
export function buildDailyWindowInvoices({
  accountId,
  currency = 'USD',
  timeZone = 'UTC',
  anchorHourLocal = 0,
  rangeStartUtcMs,
  rangeEndUtcMs,
  events = [],
  metricTiers = {},
  grants = []
} = {}) {
  const windows = enumerateDailyWindows(rangeStartUtcMs, rangeEndUtcMs, timeZone, anchorHourLocal);
  const pool = grants.map((g) => (g && typeof g === 'object' ? { ...g } : g));
  const buckets = windows.map(() => new Map());

  for (const evt of events) {
    if (!evt) continue;
    const ts = evt.timestampMs;
    if (!Number.isFinite(ts) || ts < rangeStartUtcMs || ts >= rangeEndUtcMs) continue;
    let lo = 0;
    let hi = windows.length - 1;
    let idx = -1;
    while (lo <= hi) {
      const mid = (lo + hi) >> 1;
      if (ts < windows[mid].startUtcMs) hi = mid - 1;
      else if (ts >= windows[mid].endUtcMs) lo = mid + 1;
      else {
        idx = mid;
        break;
      }
    }
    if (idx < 0) continue;
    const units = Number.isFinite(evt.units) ? evt.units : 0;
    buckets[idx].set(evt.metric, (buckets[idx].get(evt.metric) ?? 0) + units);
  }

  return windows.map((w, i) => {
    const usageRows = [...buckets[i].keys()]
      .sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))
      .map((metric) => ({ metric, units: buckets[i].get(metric), tiers: metricTiers[metric] }));
    const active = pool.filter(
      (g) =>
        g &&
        g.remainingCents > 0 &&
        (g.effectiveFromMs ?? -Infinity) <= w.startUtcMs &&
        w.startUtcMs < (g.expiresAtMs ?? Infinity)
    );
    const inv = buildInvoice({
      invoiceId: `${accountId}:${w.localDate}`,
      accountId,
      currency,
      usageRows,
      grants: active,
      asOfMs: w.startUtcMs
    });
    return { ...inv, asOfMs: w.startUtcMs, localDate: w.localDate, windowStartUtcMs: w.startUtcMs, windowEndUtcMs: w.endUtcMs };
  });
}
EOF
